<?php
declare(strict_types=1);
const ROOT = __DIR__ . '/..';
$configFile = ROOT . '/config.php';
if (!is_file($configFile)) $configFile = ROOT . '/config.example.php';
$config = require $configFile;
function web_setup_allowed(): bool { return ($GLOBALS['config']['allow_web_setup'] ?? false) === true; }
function db(): PDO { static $pdo; global $config; if (!$pdo) $pdo = new PDO($config['db']['dsn'], $config['db']['user'], $config['db']['pass'], [PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]); return $pdo; }
function session_start_safe(): void { if(session_status()!==PHP_SESSION_ACTIVE){session_name('lacustre_admin');session_set_cookie_params(['httponly'=>true,'samesite'=>'Lax','secure'=>!empty($_SERVER['HTTPS'])]);session_start();} }
function json_response(array $data,int $status=200): never {http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store, no-cache, must-revalidate');echo json_encode($data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
function input(): array {$raw=file_get_contents('php://input');return str_contains($_SERVER['CONTENT_TYPE']??'','application/json')?(json_decode($raw,true)?:[]):$_POST;}
function admin(): ?array {session_start_safe();return $_SESSION['admin']??null;}
function csrf(): string {session_start_safe();return $_SESSION['csrf']??=bin2hex(random_bytes(24));}
function require_admin(): array {$a=admin();if(!$a)json_response(['error'=>'Sesión no válida'],401);return $a;}
function require_csrf(): void {$sent=$_SERVER['HTTP_X_CSRF_TOKEN']??($_POST['csrf']??'');if(!hash_equals(csrf(),$sent))json_response(['error'=>'Solicitud expirada. Recarga e intenta nuevamente.'],419);}
function slugify(string $s): string {$s=iconv('UTF-8','ASCII//TRANSLIT',$s)?:$s;$s=strtolower(trim(preg_replace('/[^a-zA-Z0-9]+/','-',$s),'-'));return $s?:bin2hex(random_bytes(4));}
function upload(string $field,string $kind): array {global $config;if(empty($_FILES[$field])||$_FILES[$field]['error']!==UPLOAD_ERR_OK)throw new RuntimeException('Selecciona un archivo válido.');$f=$_FILES[$field];$max=$kind==='image'?$config['image_max']:$config['video_max'];if($f['size']>$max)throw new RuntimeException('El archivo supera el máximo permitido.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$allowed=$kind==='image'?['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp']:['video/mp4'=>'mp4','video/webm'=>'webm'];if(!isset($allowed[$mime]))throw new RuntimeException('Formato no permitido.');$folder=$kind==='image'?'images':'videos';$base=bin2hex(random_bytes(18));$name=$base.'.'.$allowed[$mime];$dir=ROOT.'/uploads/'.$folder;if(!is_dir($dir)&&!mkdir($dir,0755,true))throw new RuntimeException('No se pudo preparar la carpeta.');if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$name))throw new RuntimeException('No se pudo guardar el archivo.');if($kind==='image'&&function_exists('imagewebp')){$main=make_webp_variants($dir.'/'.$name,$dir,$base,$mime);if($main)return ['path'=>'uploads/images/'.$main,'mime'=>'image/webp','size'=>(int)$f['size']];}return ['path'=>'uploads/'.$folder.'/'.$name,'mime'=>$mime,'size'=>(int)$f['size']];}
function make_webp_variants(string $source,string $dir,string $base,string $mime): ?string {$raw=@file_get_contents($source);$img=$raw?@imagecreatefromstring($raw):false;if(!$img)return null;if($mime==='image/jpeg'&&function_exists('exif_read_data')){$ex=@exif_read_data($source);$o=(int)($ex['Orientation']??1);if($o===3)$img=imagerotate($img,180,0);elseif($o===6)$img=imagerotate($img,-90,0);elseif($o===8)$img=imagerotate($img,90,0);}$w=imagesx($img);$h=imagesy($img);$largest=null;foreach([480,960,1600] as $max){if($w<=$max&&$max!==1600)continue;$nw=min($w,$max);$nh=(int)round($h*($nw/$w));$out=imagecreatetruecolor($nw,$nh);imagealphablending($out,false);imagesavealpha($out,true);imagecopyresampled($out,$img,0,0,0,0,$nw,$nh,$w,$h);$file=$base.'-'.$max.'.webp';imagewebp($out,$dir.'/'.$file,82);imagedestroy($out);$largest=$file;}imagedestroy($img);return $largest;}
